import json, os, sys
rec = json.load(open('rcos-invocation-route-record-validate.json'))
inv_dir = os.path.expanduser('~/zcode-rcos/invocations') + '/' + rec['invocation_id']
payload = json.load(open(os.path.join(inv_dir, rec['output']['path'])))
problems = []
if payload.get('schema') != 'rcos-route-record-validation/1':
    problems.append('payload schema ' + str(payload.get('schema')))
rs = payload.get('records') or []
want = {
    'total': len(rs),
    'valid': sum(1 for r in rs if r.get('verdict') == 'valid'),
    'schema_violations': sum(1 for r in rs if r.get('verdict') == 'schema-violation'),
    'authority_refusals': sum(1 for r in rs if r.get('verdict') == 'authority-refusal'),
    'eligibility_refusals': sum(1 for r in rs if r.get('verdict') == 'eligibility-refusal'),
    'unreadable': sum(1 for r in rs if r.get('verdict') == 'unreadable'),
}
got = payload.get('summary') or {}
for k in want:
    if got.get(k) != want[k]:
        problems.append('summary.' + k + ' adapter=' + str(got.get(k)) + ' recount=' + str(want[k]))
frozen = {'total': 1, 'valid': 1, 'schema_violations': 0, 'authority_refusals': 0, 'eligibility_refusals': 0, 'unreadable': 0}
if want != frozen:
    problems.append('frozen arithmetic drifted: ' + json.dumps(want))
if not rs or rs[0].get('name') != 'dispatch-handoff' or rs[0].get('exit') != 0:
    problems.append('record not judged valid: ' + json.dumps(rs[:1]))
probe = (payload.get('probes') or {}).get('missing_record') or {}
if probe.get('refused') is not True or probe.get('kernel_exit') != 2:
    problems.append('missing_record probe: ' + json.dumps(probe))
verdict = 'ship' if not problems else 'fix'
out = {'schema': 'a2c-route-record-live-verdict/1', 'verdict': verdict,
      'invocation_id': rec.get('invocation_id'),
      'record_judged': 'dispatch-handoff',
      'rederived_summary': want, 'adapter_summary': got,
      'frozen_arithmetic': frozen,
      'probe_missing_record': probe, 'problems': problems}
json.dump(out, open('verdict.json', 'w'), indent=2)
print('rederive-verdict:', verdict)
if problems:
    sys.exit(1)
PYEOF
